#!/bin/sh
# Build the WebAssembly search (core.c) into core-wasm.js (base64: engine.js loads it synchronously in a worker and in Node).
# Then: node tools/check_wasm.js (the same results as the JS search)
cd "$(dirname "$0")/.."
clang --target=wasm32 -nostdlib -fno-builtin -O3 -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--allow-undefined -Wl,-z,stack-size=8388608 -Wl,--initial-memory=83886080 -o /tmp/ugolki-core.wasm core.c || exit 1
node -e "const b=require('fs').readFileSync('/tmp/ugolki-core.wasm');require('fs').writeFileSync('core-wasm.js','// generated by tools/build-core.sh from core.c — do not edit\nself.UG_WASM=\''+b.toString('base64')+'\';\n');console.log('core-wasm.js', b.length, 'bytes of wasm')"
